120	    /**
121	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
122	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
123	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
124	     * is {@code null} or its region is not in the table.
125	     */
126	    default String formatTimezone(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return Regions.timezoneForRegion(formatLocality(owner));
131	    }
